    public async Task ImportAsync(SeedDataDto data, CancellationToken ct = default)
    {
        var venues = new List<Venue>();
        var venueIds = data.Spielstaetten.Select(v => v.Id).ToHashSet();

        foreach (var eventDto in data.Veranstaltungen)
        {
            if (!venueIds.Contains(eventDto.SpielstaetteId))
            {
                throw new InvalidOperationException(
                    $"Veranstaltung '{eventDto.Id}' referenziert unbekannte Spielstätte '{eventDto.SpielstaetteId}'.");
            }
        }

        foreach (var venueDto in data.Spielstaetten)
        {
            var venue = new Venue { Name = venueDto.Name };
            var roomsById = new Dictionary<string, Room>();

            foreach (var roomDto in venueDto.Raeume)
            {
                if (!roomsById.TryAdd(roomDto.Id, new Room
                {
                    Name = roomDto.Name,
                    RowLabels = roomDto.Reihen,
                    ColumnCount = roomDto.Spalten,
                    AisleColumns = roomDto.Gang?.Spalten ?? new List<int>(),
                }))
                {
                    throw new InvalidOperationException(
                        $"Spielstätte '{venueDto.Id}' enthält den Raum '{roomDto.Id}' mehrfach.");
                }

                venue.Rooms.Add(roomsById[roomDto.Id]);
            }

            foreach (var eventDto in data.Veranstaltungen.Where(e => e.SpielstaetteId == venueDto.Id))
            {
                if (!roomsById.TryGetValue(eventDto.RaumId, out var room))
                {
                    throw new InvalidOperationException(
                        $"Veranstaltung '{eventDto.Id}' referenziert unbekannten Raum '{eventDto.RaumId}' in Spielstätte '{venueDto.Id}'.");
                }

                var @event = new Event
                {
                    Titel = eventDto.Titel,
                    Beschreibung = eventDto.Beschreibung,
                    Zeitpunkt = eventDto.Zeitpunkt,
                    DauerMinuten = eventDto.DauerMinuten,
                    Altersfreigabe = eventDto.Altersfreigabe,
                };

                foreach (var priceCategoryDto in eventDto.Preiskategorien)
                {
                    @event.PriceCategories.Add(new PriceCategory
                    {
                        Name = priceCategoryDto.Name,
                        Preis = priceCategoryDto.Preis,
                    });
                }

                var gesehen = new HashSet<(string RowLabel, int ColumnNumber)>();
                foreach (var sitzplatz in eventDto.BelegteSitzplaetze)
                {
                    var (rowLabel, columnNumber) = ParseSitzplatz(sitzplatz);

                    if (!gesehen.Add((rowLabel, columnNumber)))
                    {
                        throw new InvalidOperationException(
                            $"Veranstaltung '{eventDto.Id}' listet den Sitzplatz '{sitzplatz}' mehrfach in 'belegteSitzplaetze'.");
                    }

                    if (!room.RowLabels.Contains(rowLabel) || columnNumber < 1 || columnNumber > room.ColumnCount)
                    {
                        throw new InvalidOperationException(
                            $"Veranstaltung '{eventDto.Id}': Sitzplatz '{sitzplatz}' liegt außerhalb des Sitzplans von Raum '{eventDto.RaumId}'.");
                    }

                    if (room.AisleColumns.Contains(columnNumber))
                    {
                        throw new InvalidOperationException(
                            $"Veranstaltung '{eventDto.Id}': Sitzplatz '{sitzplatz}' liegt auf einer Gang-Spalte von Raum '{eventDto.RaumId}'.");
                    }

                    @event.BookingPositions.Add(new BookingPosition
                    {
                        RowLabel = rowLabel,
                        ColumnNumber = columnNumber,
                        BookingId = null,
                        PriceCategoryId = null,
                        CancelledAtUtc = null,
                    });
                }

                room.Events.Add(@event);
            }

            venues.Add(venue);
        }

        db.Venues.AddRange(venues);
        await db.SaveChangesAsync(ct);
    }

    /// <summary>Führende Buchstaben = RowLabel, folgende Ziffern = ColumnNumber (z. B. "B3" -> ("B", 3)).</summary>
    internal static (string RowLabel, int ColumnNumber) ParseSitzplatz(string sitzplatz)
    {
        var digitsStart = 0;
        while (digitsStart < sitzplatz.Length && char.IsAsciiLetter(sitzplatz[digitsStart]))
        {
            digitsStart++;
        }

        var digitsEnd = digitsStart;
        while (digitsEnd < sitzplatz.Length && char.IsAsciiDigit(sitzplatz[digitsEnd]))
        {
            digitsEnd++;
        }

        if (digitsStart == 0 || digitsStart == sitzplatz.Length || digitsEnd != sitzplatz.Length)
        {
            throw new FormatException($"Sitzplatz '{sitzplatz}' entspricht nicht dem Format <Reihenbuchstaben><Spaltenzahl>.");
        }

        var rowLabel = sitzplatz[..digitsStart];
        var columnNumber = int.Parse(sitzplatz[digitsStart..]);
        return (rowLabel, columnNumber);
    }
}

