        {
            throw new FormatException($"Sitzplatz '{sitzplatz}' entspricht nicht dem Format <Reihenbuchstaben><Spaltenzahl>.");
        }

        var rowLabel = sitzplatz[..digitsStart];
        return (rowLabel, columnNumber);
    }
}

